// Kata bahasa Indonesia 4-6 huruf, dari gabungan 5 kamus di
// github.com/geovedi/indonesian-wordlist.
//
// Sebuah kata dihitung "umum" kalau muncul di banyak kamus sekaligus, jadi
// ambang kemunculan dipakai sebagai pengganti data frekuensi:
//   WORDS   = muncul di >= 2 kamus (tebakan yang diterima)
//   ANSWERS = muncul di kelima kamus DAN masuk 20.000 kata tersering di
//             github.com/hermitdave/FrequencyWords (id_50k), tanpa kata kasar/sensitif.
//             Ditambah manual: itpln, sapi, ular.
//
// Daftarnya disimpan sebagai satu string dipisah spasi lalu di-split: menulis
// array literal menambah tanda kutip dan koma untuk tiap kata, sekitar 40 KB
// lebih besar untuk isi yang sama.
//
// ponytail: ikut bundel utama. Pindahkan ke import() dinamis di Furdle kalau
// ukuran muatan awal halaman mulai terasa.

import { SLOTS, quoteAt, quoteCount } from "./quotes";

export type Len = 4 | 5 | 6;

/** Panjang kata yang bisa dipilih pemain. */
