// Kata dari kalimat penyemangat (lib/quotes.ts) ikut jadi tebakan dan jawaban,
// termasuk kata santai seperti "nggak" yang tidak ada di kamus.
const QUOTE_TEXT = SLOTS.flatMap((s) =>
  Array.from({ length: quoteCount(s) }, (_, i) => quoteAt(s, i)),
).join(" ").toLowerCase();

const merge = (base: Record<Len, readonly string[]>): Record<Len, readonly string[]> => {
  const extra = QUOTE_TEXT.split(/[^a-z]+/);
  const out = {} as Record<Len, readonly string[]>;
  for (const n of LENGTHS) out[n] = [...new Set([...base[n], ...extra.filter((w) => w.length === n)])];
  return out;
};

/** Tebakan yang dianggap sah, per panjang kata. */
export const WORDS = merge(BASE_WORDS);

/** Kandidat jawaban, per panjang kata. Selalu bagian dari WORDS. */
export const ANSWERS = merge(BASE_ANSWERS);
